{
  "name": "Invoice",
  "schema_definition": {
    "type": "object",
    "title": "Invoice",
    "properties": {
      "invoice_number": {
        "type": "string",
        "title": "Invoice Number"
      },
      "vendor_name": {
        "type": "string",
        "title": "Vendor Name"
      },
      "vendor_address": {
        "type": "string",
        "title": "Vendor Address"
      },
      "invoice_date": {
        "type": "string",
        "format": "date",
        "title": "Invoice Date"
      },
      "due_date": {
        "type": "string",
        "format": "date",
        "title": "Due Date"
      },
      "currency": {
        "type": "string",
        "title": "Currency",
        "enum": ["USD", "EUR", "GBP", "INR", "CAD", "AUD"]
      },
      "subtotal": {
        "type": "number",
        "title": "Subtotal"
      },
      "tax_total": {
        "type": "number",
        "title": "Tax Total"
      },
      "total_amount": {
        "type": "number",
        "title": "Total Amount"
      },
      "status": {
        "type": "string",
        "title": "Status",
        "enum": ["Pending", "Approved", "Paid", "Rejected"]
      },
      "notes": {
        "type": "string",
        "title": "Notes"
      },
      "line_items": {
        "type": "array",
        "title": "Line Items",
        "items": {
          "type": "object",
          "properties": {
            "item_code": {
              "type": "string",
              "title": "Item Code"
            },
            "description": {
              "type": "string",
              "title": "Description"
            },
            "quantity": {
              "type": "number",
              "title": "Quantity"
            },
            "unit_price": {
              "type": "number",
              "title": "Unit Price"
            },
            "line_total": {
              "type": "number",
              "title": "Line Total"
            },
            "tax_rate": {
              "type": "number",
              "title": "Tax Rate (%)"
            },
            "tax_amount": {
              "type": "number",
              "title": "Tax Amount"
            }
          },
          "required": ["item_code", "description", "quantity", "unit_price", "line_total"]
        }
      }
    },
    "required": ["invoice_number", "vendor_name", "invoice_date", "total_amount", "line_items"]
  }
}
